def render(md):
 chunks=re.split(r'\n\s*\n',md.strip()); out=''
 for c in chunks:
  lines=c.splitlines(); text=' '.join(lines)
  if len(lines)==1 and (text.startswith(('1. ','2. ','3. ')) or text in ['What has to be known?','An example','What to record']): out+='<h2>'+html.escape(text)+'</h2>'; continue
  text=html.escape(text); text=re.sub(r'\[([^]]+)\]\((https?://[^)]+)\)',r'<a href="\2">\1</a>',text);out+='<p>'+text+'</p>'
 return out
